function minSubArrayLen(target: number, nums: number[]): number {
  let left = 0;
  let sum = 0; // сумма текущего окна [left, right]
  let best = Infinity;

  for (let right = 0; right < nums.length; right++) {
    // Расширяем окно вправо
    sum += nums[right];

    // Пока окно «достаточно большое» — пробуем его сузить слева
    while (sum >= target) {
      best = Math.min(best, right - left + 1);
      sum -= nums[left];
      left++;
    }
  }

  // Ни одно окно не набрало target
  return best === Infinity ? 0 : best;
}

// Время: O(n) — каждый элемент входит в окно и выходит из него по одному разу
// Память: O(1)
